S=(GX,GE); L=(GXL,GEL)
LESSONS=(
make_lesson(281,"Lesson_281-metamorphic-and-property-tests-for-pipelines","Metamorphic and property tests for pipelines","wiki.data-quality.metamorphic-property-tests","Khi không có expected output đầy đủ, metamorphic relation và property nào vẫn có thể phát hiện pipeline sai?",S,L,a(
"Oracle problem|Nhiều pipeline khó có golden output lớn; property kiểm invariant còn metamorphic relation kiểm quan hệ giữa các executions.","Useful relations|Permutation, duplication, partitioning, scale, rename-compatible và irrelevant-column transforms phải có expected relation rõ.","Domain properties|Conservation, idempotence, monotonicity, boundedness và referential closure phải gắn domain chứ không chọn vì dễ viết.","Generator discipline|Sinh dữ liệu phải giữ valid preconditions rồi shrink failure về counterexample nhỏ có seed tái hiện.","Invalid relations|Aggregate distinct, floating arithmetic, nondeterministic tie và approximate algorithm có thể phá relation ngây thơ.","Evidence package|Lưu base input, transformation, both outputs, relation verdict, seed và minimized counterexample.")),
make_lesson(282,"Lesson_282-statistical-anomaly-detection-and-its-cost","Statistical anomaly detection and its cost","wiki.data-quality.statistical-anomaly-cost","Anomaly detector được đánh giá bằng detection value, false-positive cost và compute cost như thế nào?",S,L,a(
"Signal definition|Metric, grain, cadence, seasonality và business segmentation phải ổn định trước khi fit threshold.","Baseline and drift|Rolling history có contamination, trend và regime change; baseline cần exclusion policy và version.","Detector choices|Static bands, robust z-score, seasonal residual và forecast interval có assumption/cost khác nhau.","Error economics|Precision, recall, delay và missed-impact phải quy về triage load, user harm và remediation value.","Compute footprint|Profiling, scan, state retention và cardinality làm observability thành workload cần budget.","Shadow rollout|Backtest rồi chạy shadow, label outcomes, điều chỉnh threshold có review; không tune theo từng alert cho tới im lặng.")),
make_lesson(283,"Lesson_283-backtesting-rules-against-known-incidents","Backtesting rules against known incidents","wiki.data-quality.backtesting-known-incidents","Backtest rule thế nào để đo detection coverage mà không rò nhãn sự cố vào threshold?",S,L,a(
"Incident corpus|Mỗi incident cần affected assets, start/end, defect class, impact, known signals và evidence confidence.","Leakage boundary|Tách development và holdout incidents theo thời gian/họ lỗi; không dùng root-cause knowledge tương lai khi mô phỏng.","Replay fidelity|Khôi phục data snapshots hoặc feature traces gần thời điểm đó; synthetic replay phải ghi điểm khác thực tế.","Scoring|Đo detected, missed, early/late, false pages và ambiguous; một incident có nhiều alerts không thành nhiều true positives.","Counterfactual action|Alert chỉ có giá trị nếu runbook/owner có thể hành động trước impact; detection sau publication không phải prevention.","Change control|Rule version, threshold rationale, holdout result và regression suite trở thành release evidence.")),
make_lesson(284,"Lesson_284-the-reconciliation-ladder-seven-levels","The reconciliation ladder - seven levels","wiki.data-quality.reconciliation-ladder","Bảy mức reconciliation tăng độ mạnh từ presence tới record semantics như thế nào?",S,L,a(
"Presence and manifest|Mức đầu xác nhận object/partition/file expected có mặt, size/checksum envelope hợp lệ; chưa nói nội dung đúng.","Counts|Row/event counts theo partition và status phát hiện loss/gain nhưng không thấy bù trừ.","Control totals|Sum/min/max/distinct theo dimensions tăng sensitivity nhưng type, currency và null policy phải đồng nhất.","Key sets|Anti-join và multiset comparison lộ missing, extra và multiplicity; cần normalize identity trước.","Record hashes|Typed canonical row hash phát hiện value drift, nhưng ordering, null và floating normalization phải cố định.","Business invariants and sampling|Cấp cao nhất nối ledger/domain invariant với drill-down; sampling chỉ bổ sung, không thay population proof.")),
make_lesson(285,"Lesson_285-normalization-before-comparison","Normalization before comparison","wiki.data-quality.normalization-before-comparison","Canonicalization nào cần làm trước reconciliation mà không xóa khác biệt có ý nghĩa?",S,L,a(
"Type normalization|String-number, decimal scale, timestamp precision và boolean encodings cần typed target có loss policy.","Text normalization|Unicode form, whitespace, case và locale chỉ áp khi business identity cho phép; tên riêng không mặc nhiên case-insensitive.","Temporal normalization|Convert instant bằng known timezone, giữ original local/offset khi ambiguity có ý nghĩa.","Null and absence|NULL, empty, zero, missing field và sentinel là states khác nhau trừ khi contract hợp nhất chúng.","Collection ordering|Chỉ sort arrays/maps khi semantics là set; event sequence và repeated fields có thể order-sensitive.","Canonical hash contract|Serialize field names, types, null markers, separators và version trước hash; collision/algorithm migration phải có kế hoạch.")),
)
QUERIES={n:[f"L{n} oracle nào phù hợp?",f"L{n} counterexample nào bắt buộc?",f"L{n} giới hạn kết luận là gì?"] for n in range(281,286)}
VERIFY={n:"Chạy fixture gốc và biến đổi/đối chiếu độc lập, giữ seed hoặc canonicalization version và chứng minh ít nhất một negative case bị bắt." for n in range(281,286)}
TAKEAWAYS={281:"Metamorphic testing kiểm quan hệ giữa executions khi golden output không khả thi.",282:"Detector chỉ tốt khi detection value lớn hơn false-positive và compute cost.",283:"Backtest cần holdout incidents và replay không dùng tri thức tương lai.",284:"Reconciliation mạnh dần từ presence tới key, record và business invariants.",285:"Normalization là contract có version; canonicalization quá tay có thể che defect."}
